{
  "type": "layerDiagram",
  "title": "Feature to engine boundary",
  "summary": "Dependencies flow from feature to engine.",
  "layers": [
    {
      "id": "feature",
      "label": "Feature",
      "role": "consumer",
      "summary": "Consumes the public surface.",
      "nodes": [
        { "id": "home-page", "label": "HomePage", "detail": "Declares WorldStage and WorldLayout." }
      ],
      "transition": "Places WorldSurface in the widget tree."
    },
    {
      "id": "surface",
      "label": "Surface",
      "role": "surface",
      "summary": "Owns the public Flutter API.",
      "nodes": [
        { "id": "world-surface", "label": "WorldSurface", "detail": "Creates and owns the session." }
      ]
    }
  ]
}

{
  "type": "flowDiagram",
  "title": "Artifact projection flow",
  "summary": "A validated handle flows from persistence to projection.",
  "nodes": [
    { "id": "persist", "label": "Persist", "detail": "Creates the handle.", "role": "value" },
    { "id": "project", "label": "Project", "detail": "Reads persisted artifacts.", "role": "surface" }
  ],
  "edges": [
    { "from": "persist", "to": "project", "label": "provides handle" }
  ]
}

{
  "type": "relationDiagram",
  "title": "Runtime ownership",
  "summary": "WorldStage creates WorldLayout, which adapts to M3SpatialScene.",
  "nodes": [
    { "id": "stage", "label": "WorldStage", "detail": "Immutable feature input.", "role": "value" },
    { "id": "layout", "label": "WorldLayout", "detail": "Session-owned runtime handle.", "role": "session" },
    { "id": "scene", "label": "M3SpatialScene", "detail": "Engine-owned resource.", "role": "boundary" }
  ],
  "relations": [
    { "from": "stage", "to": "layout", "label": "creates" },
    { "from": "layout", "to": "scene", "label": "adapts" }
  ]
}
